  Context {fx : OssFuzzTheorems.Proofs.boost_json.fuzz_parse.lib.PropExec.FPState}.
  Variable segs : ltac2:(zQ "20!h8!mnd@1$0$1").
  Variable base : word.
  Variable mem0 : ltac2:(zQ "30!j7!lb!mh6>0@1$1@1$0#k0@1$2@1$1@1$0#8").
